import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Editing entries via form","description":"Let people change existing entries via a form — without access to the Space.","frontmatter":{"title":"Editing entries via form","description":"Let people change existing entries via a form — without access to the Space."},"headers":[],"relativePath":"en/formulare/eintraege-bearbeiten.md","filePath":"en/formulare/eintraege-bearbeiten.md","lastUpdated":1787319236000}'),r={name:"en/formulare/eintraege-bearbeiten.md"};function i(s,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="editing-entries-via-form" tabindex="-1">Editing entries via form <a class="header-anchor" href="#editing-entries-via-form" aria-label="Permalink to &quot;Editing entries via form&quot;">​</a></h1><p>Forms don&#39;t only create new entries. They can also open an <strong>existing</strong> entry for editing — for people who don&#39;t have access to the Space.</p><h2 id="what-it-s-good-for" tabindex="-1">What it&#39;s good for <a class="header-anchor" href="#what-it-s-good-for" aria-label="Permalink to &quot;What it&#39;s good for&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Use</th><th>Flow</th></tr></thead><tbody><tr><td><strong>Request a correction</strong></td><td>You send a link, the person corrects their information</td></tr><tr><td><strong>Get an RSVP</strong></td><td>The entry already exists, only the status is missing</td></tr><tr><td><strong>Collect additional documents</strong></td><td>A file field gets filled in</td></tr><tr><td><strong>Confirm data</strong></td><td>Annual review of master data</td></tr><tr><td><strong>Feedback from a Flow</strong></td><td>A <a href="/en/flows/aktionen">Flow</a> sends the link automatically</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">No duplicate entries</p><p>The key difference from a regular form: <strong>no second record</strong> is created. The change lands in the existing entry.</p><p>Without this approach, people often send their correction through the same registration form again — and you end up with the process duplicated.</p></div><h2 id="sharing-an-entry-for-editing" tabindex="-1">Sharing an entry for editing <a class="header-anchor" href="#sharing-an-entry-for-editing" aria-label="Permalink to &quot;Sharing an entry for editing&quot;">​</a></h2><ol><li>Open the entry&#39;s row menu.</li><li>Choose <strong>Share entry</strong>.</li><li>Under <em>Choose a form</em>, select the form to use.</li></ol><p>The dialog is called:</p><blockquote><p><strong>Share form for editing</strong><em>Share a form to edit the entry with others.</em></p></blockquote><p>After creating it:</p><blockquote><p><em>We&#39;ve securely published your entry, and it&#39;s available at the following web address.</em></p></blockquote><div class="warning custom-block"><p class="custom-block-title">A form is required</p><p>Without a form on this Grid, you&#39;ll see: <em>Create a form first to share the entry with others.</em></p><p>Create a <a href="/en/formulare/formular-erstellen">form</a> first — ideally one that contains exactly the fields that should be editable.</p></div><h2 id="from-a-flow" tabindex="-1">From a Flow <a class="header-anchor" href="#from-a-flow" aria-label="Permalink to &quot;From a Flow&quot;">​</a></h2><p>The Flow step <strong>Prefilled form link</strong> generates the same link automatically.</p><p>That&#39;s how you build feedback loops without manual work:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: Entry was changed  (Status = &quot;Review needed&quot;)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Prefilled form link         → generates the editing link</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Email                       → sends it to the person</span></span></code></pre></div><p>When the person submits the form, the trigger <strong>Entry changed via form</strong> fires — allowing another Flow to process the feedback.</p><p>→ <a href="/en/flows/trigger">Triggers</a> · <a href="/en/flows/aktionen">Actions</a></p><h2 id="preparing-a-form-for-editing" tabindex="-1">Preparing a form for editing <a class="header-anchor" href="#preparing-a-form-for-editing" aria-label="Permalink to &quot;Preparing a form for editing&quot;">​</a></h2><p>An editing form should be built differently from a data-collection form:</p><div class="tip custom-block"><p class="custom-block-title">Only show what&#39;s allowed to change</p><table tabindex="0"><thead><tr><th>Goal</th><th>Setting</th></tr></thead><tbody><tr><td>Show a field but don&#39;t allow changes</td><td><strong>Not editable</strong></td></tr><tr><td>Don&#39;t show a field at all</td><td><strong>Not visible</strong> or remove it from the form</td></tr><tr><td>Protect existing files</td><td><strong>Allow adding files only</strong></td></tr><tr><td>Display only, no editing</td><td><strong>Hide submit button</strong></td></tr></tbody></table><p><em>Hide submit button</em> is explicitly meant for this — the interface describes it as: <em>This is useful if you&#39;re using the form to share a view of an entry with others.</em></p></div><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">The link opens exactly this entry</p><p>Anyone with the link can view — and, depending on the form, edit — the entry. There&#39;s no additional check of who the person is.</p><p>Handle the link accordingly:</p><ul><li>Send it only to the person concerned.</li><li>Restrict access via <strong>Set restrictions</strong> if the entry is sensitive.</li><li>Remove the link once it&#39;s no longer needed.</li></ul></div><p>For form links, the access model is <strong>Everyone</strong> / <strong>Every registered user</strong> / <strong>Everyone in this Space</strong>. → <a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></p><div class="tip custom-block"><p class="custom-block-title">Account confirmation for sensitive processes</p><p><strong>Show account confirmation notice</strong> lets people filling out the form see which account they&#39;re signed in as. On shared devices, this prevents someone confirming under the wrong name.</p></div><h2 id="removing-a-link" tabindex="-1">Removing a link <a class="header-anchor" href="#removing-a-link" aria-label="Permalink to &quot;Removing a link&quot;">​</a></h2><p>Via the share dialog or in the <a href="/en/zusammenarbeit/externe-links">links overview</a> of the Space. A removed link stops working immediately.</p><div class="tip custom-block"><p class="custom-block-title">Clean up once finished</p><p>Editing links often pile up during regular operation — especially when a Flow generates them. Check the links overview regularly and remove what&#39;s done.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/formular-teilen">Sharing a form</a></li><li><a href="/en/formulare/vorausgefuellte-links">Prefilled links</a></li><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li></ul>`,30)])])}const f=t(r,[["render",i]]);export{g as __pageData,f as default};
